top_customer_by_transactions = Customers.CALCULATE(
    num_transactions_in_signup_month=COUNT(transactions_made.WHERE((YEAR(date_time) == YEAR(join_date)) & (MONTH(date_time) == MONTH(join_date))))
).TOP_K(
    1, 
    by=num_transactions_in_signup_month.DESC()
).CALCULATE(
    _id=_id,
    name=name,
    num_transactions=num_transactions_in_signup_month
)

