result = Ewallet.CALCULATE(
    earliest_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_monthly)
)

# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for that specific date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_monthly
    )
)

average_limits = Ewallet.CALCULATE(
    min_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_date_2023).tx_limit_monthly)
)

earliest_snapshot_limits = Ewallet.CALCULATE(
    earliest_date_in_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_in_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_in_2023).tx_limit_monthly)
)

# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for that specific date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_monthly
    )
)

earliest_snapshot_limits = Ewallet.CALCULATE(
    min_snapshot_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_snapshot_date_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == min_snapshot_date_2023).tx_limit_monthly)
)

